<template><section class="admin-panel"><header class="admin-section-head"><div><p>TRUTHFUL SNAPSHOT</p><h1>运行概览</h1></div><button type="button" @click="$emit('retry')">读取快照</button></header><AdminState :loading="loading" :error="error" @retry="$emit('retry')"/><template v-if="!loading&&!error"><div class="admin-summary-grid"><article v-for="item in summary" :key="item.label"><span>{{ item.label }}</span><strong>{{ item.value }}</strong></article></div><div class="admin-metric-sections"><section v-for="group in groups" :key="group.key" class="admin-metric-group"><header><div><strong>{{ group.label }}</strong><small>{{ group.description }}</small></div><span :class="['metric-status',section(group.section).status.toLowerCase()]">{{ statusText(section(group.section).status) }}</span></header><p v-if="section(group.section).status!=='AVAILABLE'" class="admin-section-warning">{{ sectionHint(group.section) }}</p><div class="admin-metric-grid"><article v-for="metric in group.metrics" :key="metric.label"><span>{{ metric.label }}</span><strong>{{ metric.value }}</strong><small v-if="metric.hint">{{ metric.hint }}</small></article></div></section></div><p class="admin-sampled">采样时间：{{ dashboard.sampledAt || '尚未完成首次采样' }}</p></template></section></template>
<script setup lang="ts">
import { computed } from "vue"; import type { AdminDashboard, MetricSectionStatus } from "../../services/admin"; import AdminState from "./AdminState.vue";
const props=defineProps<{dashboard:AdminDashboard;loading:boolean;error?:string}>(); defineEmits<{retry:[]}>();
const value=(v:unknown,suffix="")=>v===null||v===undefined||v==="UNAVAILABLE"?"不可用":`${v}${suffix}`;
const section=(key:string):MetricSectionStatus=>props.dashboard.sections?.[key]||{status:"UNAVAILABLE",errorCode:"METRICS_UNAVAILABLE"};
const statusText=(v:string)=>v==="AVAILABLE"?"可用":v==="STALE"?"旧快照":"不可用";
const sectionHint=(key:string)=>section(key).status==="STALE"?`采样失败，显示 ${section(key).sampledAt||"此前"} 的最后有效值。`:`当前无法读取该分区（${section(key).errorCode||"METRICS_UNAVAILABLE"}）。`;
const summary=computed(()=>[{label:"在线用户",value:value(props.dashboard.onlineUsers)},{label:"今日动态",value:value(props.dashboard.todayPosts)},{label:"待看反馈",value:value(props.dashboard.pendingFeedback)},{label:"系统状态",value:value(props.dashboard.systemStatus)}]);
const groups=computed(()=>[
 {key:"system",section:"system",label:"系统与 JVM",description:"主机、磁盘与运行时",metrics:[{label:"CPU",value:value(props.dashboard.cpuUsage,"%")},{label:"JVM 内存",value:value(props.dashboard.jvmMemoryUsage,"%")},{label:"系统内存",value:value(props.dashboard.systemMemoryUsage,"%")},{label:"磁盘",value:value(props.dashboard.diskUsage,"%"),hint:`${value(props.dashboard.diskFreeSpace)} / ${value(props.dashboard.diskTotalSpace)}`},{label:"磁盘吞吐",value:value(props.dashboard.diskReadRate),hint:`写入 ${value(props.dashboard.diskWriteRate)}`},{label:"网络",value:value(props.dashboard.networkReceiveRate),hint:`发送 ${value(props.dashboard.networkTransmitRate)}`},{label:"线程",value:value(props.dashboard.activeThreads),hint:`峰值 ${value(props.dashboard.peakThreads)}`},{label:"运行时间",value:value(props.dashboard.uptime)}]},
 {key:"database",section:"database",label:"数据库",description:"连接池与慢查询",metrics:[{label:"活跃连接",value:value(props.dashboard.dbActiveConnections),hint:`总计 ${value(props.dashboard.dbTotalConnections)}`},{label:"等待线程",value:value(props.dashboard.dbThreadsAwaitingConnection)},{label:"慢查询",value:value(props.dashboard.slowQueryCount),hint:`近一分钟 ${value(props.dashboard.recentSlowQueryCount)}`}]},
 {key:"redis",section:"redis",label:"Redis",description:"缓存可用性",metrics:[{label:"状态",value:value(props.dashboard.redisStatus)},{label:"命中率",value:value(props.dashboard.redisHitRate,"%")},{label:"延迟",value:value(props.dashboard.redisLatencyMs,"ms")}]},
 {key:"http",section:"http",label:"HTTP",description:"请求与错误",metrics:[{label:"每分钟请求",value:value(props.dashboard.requestsPerMinute)},{label:"累计请求",value:value(props.dashboard.requestCount)},{label:"4xx / 5xx",value:`${value(props.dashboard.http4xxCount)} / ${value(props.dashboard.http5xxCount)}`},{label:"错误率",value:value(props.dashboard.httpErrorRate,"%")}]}]);
</script>
